      "nextcloud_username" = {
        sopsFile = ../../secrets/nextcloud-credentials-lucie-sync.enc.json;
        format = "json";
        key = "username";
      };

      "nextcloud_password" = {
        sopsFile = ../../secrets/nextcloud-credentials-lucie-sync.enc.json;
        format = "json";
        key = "password";
      };
    };
  };

}

