      has_reasoning_efforts = true;
      default_reasoning_effort = "medium";
      supports_attachments = true;
    }
    {
      id = "gpt-5.1";
      name = "GPT-5.1";
      context_window = 400000;
      default_max_tokens = 128000;
      can_reason = true;
      has_reasoning_efforts = true;
      default_reasoning_effort = "medium";
      supports_attachments = true;
    }
  ];

  mucieModels = [
    {
      id = "gemma-4-26b-a4b-it-4bit";
      name = "gemma4:e4b (omlx @mucie)";
    }
  ];

  # Self-hosted Ollama instance. Uses Ollama's OpenAI-compatible endpoint
  # so we declare provider type "openai" with a custom base_url.
  # context_window is set to 65536 which requires Ollama to run with
  # `num_ctx >= 65536`. On lucie KV cache is quantized to q8_0 and flash
  # attention is enabled (see hosts/lucie/default.nix), so a 64k cache
  # fits fully on the RTX 5090's 32 GB VRAM alongside the model weights.
  lucieModels = [
    {
      id = "gemma4:26b";
      name = "Gemma 4 26B (ollama @lucie)";
      context_window = 65536;
      default_max_tokens = 4096;
    }
    {
      id = "qwen3.6:27b";
      name = "Qwen 3.6 (ollama @lucie)";
      context_window = 65536;
      default_max_tokens = 4096;
    }
    {
      id = "qwen3-coder:30b-a3b-q4_K_M";
      name = "Qwen 3.6 Coder (ollama @lucie)";
      context_window = 65536;
      default_max_tokens = 4096;
    }
  ];

  crushConfig = {
    "$schema" = "https://charm.land/crush.json";
    providers = {
      openai = {
        type = "openai";
        api_key = "$OPENAI_API_KEY";
        models = openaiModels;
      };
      # Local Ollama endpoint. Use Crush's dedicated `ollama` provider type
      # (not `openai`, which targets genuine OpenAI) so tool calls go through
      # Ollama's native parsing instead of leaking the model's raw tool-call
      # syntax (e.g. `<function=...></tool_call>`) into the chat as text.
      lucie = {
        type = "ollama";
        base_url = "http://10.100.0.100:11434/v1/";
        api_key = "ollama";
        models = lucieModels;
      };
      mucie = {
        type = "openai";
        base_url = "http://127.0.0.1:8000/v1";
        api_key = "asdfasdf";
        models = mucieModels;
      };
    };
    models = {
      large = {
        model = "gpt-5.1-codex";
        provider = "openai";
      };
      small = {
        model = "gpt-5.1";
        provider = "openai";
      };
    };
    mcp = mcpServers;
    options = {
      tui = {
        # Start in compact layout (sidebar hidden). Toggle at runtime with
        # Ctrl+P -> "Toggle Sidebar" (visible only when terminal >= 120 cols).
        compact_mode = true;
      };
      attribution = {
        generated_with = false;
        trailer_style = "none";
      };
    };
  };
in
{
  home.packages = [ pkgs.crush ];

  xdg.configFile."zsh/crush.zsh".text = ''
    alias crush="crush --yolo"
  '';

  xdg.configFile."crush/crush.json".text = builtins.toJSON crushConfig;
}

