2	{
3	  config,
4	  pkgs,
5	  lib,
6	  ...
7	}:
8	let
9	  mcp-server-github-wrapper = pkgs.callPackage ../mcp/mcp-server-github-wrapper.nix {
10	    inherit config;
11	  };
12	  mcp-server-kubectl-wrapper = pkgs.callPackage ../mcp/mcp-server-kubectl-wrapper.nix { };
13	
14	  # `codex` wrapped to inject LITELLM_API_KEY from the sops-decrypted master
15	  # key at runtime (see ./codex-wrapper.nix).
16	  codex-wrapper = pkgs.callPackage ./codex-wrapper.nix { inherit config; };
17	
18	  cfg = config.programs.mcp;
19	
20	  # Build MCP servers configuration for Codex.
21	  # Codex reads ~/.codex/config.toml with [mcp_servers.<name>] tables.
22	  # STDIO servers use `command`/`args`; remote servers use `url`.
23	  mcpServers =
24	    { }
25	    // (lib.optionalAttrs cfg.enableAtlassian {
