62	      };
63	    })
64	    // (lib.optionalAttrs cfg.enablePlaywright {
65	      playwright = {
66	        command = "${pkgs.playwright-mcp}/bin/playwright-mcp";
67	      };
68	    })
69	    // (lib.optionalAttrs cfg.enableSequentialThinking {
70	      "sequential-thinking" = {
