75	      Grafana = {
76	        url = "https://grafana-mcp-internal.qa-prometheus.qa.redislabs.com/sse";
77	      };
78	    })
79	    // (lib.optionalAttrs cfg.enableTempo {
80	      "tempo-mcp" = {
81	        url = "https://tempo-query-internal.qa-prometheus-extras.qa.redislabs.com/api/mcp";
82	      };
83	    });
