85	  # Self-hosted models served through the LiteLLM proxy on lucie
86	  # (hosts/lucie/litellm.nix, port 14000, reached over WireGuard at
87	  # 10.100.0.100). LiteLLM exposes an OpenAI-compatible API including the
88	  # Responses endpoint (/v1/responses), which recent Codex requires
89	  # (`wire_api = "chat"` was removed, see openai/codex#7782). The proxy needs
90	  # the LiteLLM master key: export it as LITELLM_API_KEY in the shell that runs
91	  # `codex`. Model IDs must match `model_name` entries in the LiteLLM config.
92	  litellmModels = {
93	    qwen-coder = "qwen3-coder:30b-a3b-q4_K_M";
94	    qwen-coder-next = "qwen3-coder-next:q4_K_M";
95	  };
96	
97	  tomlFormat = pkgs.formats.toml { };
98	
99	  # As of Codex 0.134 the legacy `[profiles.<name>]` table in config.toml is
100	  # rejected; each profile must live in its own ~/.codex/<name>.config.toml
101	  # with top-level keys. Provider definitions stay shared in the base
102	  # config.toml. Select one with e.g. `codex --profile qwen-coder`.
103	  #
104	  # These models are not in Codex's built-in catalog, so it falls back to
105	  # generic metadata ("Model metadata not found ...") — mainly the context
106	  # window, which drives context sizing and auto-compaction. Pin it to the
107	  # value Ollama actually serves on lucie (OLLAMA_CONTEXT_LENGTH = 65536, see
108	  # hosts/lucie/default.nix) so Codex sizes the window correctly.
109	  ollamaContextWindow = 65536;
110	
111	  codexProfileFiles = lib.mapAttrs' (
112	    name: model:
113	    lib.nameValuePair ".codex/${name}.config.toml" {
114	      source = tomlFormat.generate "codex-${name}.config.toml" {
115	        inherit model;
116	        model_provider = "litellm";
117	        model_context_window = ollamaContextWindow;
118	      };
119	    }
120	  ) litellmModels;
121	
122	  # Codex persists runtime state (notably per-directory trust decisions) back
123	  # into config.toml, so it cannot be a read-only Nix store symlink — writes
124	  # fail with "failed to persist config". Generate the file in the store and
125	  # install a writable copy via an activation script instead. It is
126	  # force-refreshed on every switch, which also keeps the MCP server store
127	  # paths current; the trade-off is that trust entries Codex records at runtime
128	  # for directories not pre-declared below are reset on the next switch.
129	  # (Per-profile files above are read-only — Codex only reads them.)
130	  codexConfig = tomlFormat.generate "codex-config.toml" {
131	    mcp_servers = mcpServers;
132	
133	    model_providers.litellm = {
134	      name = "LiteLLM (lucie)";
135	      base_url = "http://10.100.0.100:14000/v1";
136	      env_key = "LITELLM_API_KEY";
137	      wire_api = "responses";
138	    };
139	
140	    # Pre-trust this dotfiles repo so Codex does not prompt (and try to write)
141	    # on startup here. Add more project roots as needed.
142	    projects."${config.home.homeDirectory}/Projects/github.com/gotha/dotfiles".trust_level = "trusted";
143	  };
144	in
145	{
146	  home.packages = [ codex-wrapper ];
147	
148	  home.file = codexProfileFiles;
149	
150	  home.activation.codexConfig = lib.hm.dag.entryAfter [ "writeBoundary" ] ''
151	    $DRY_RUN_CMD rm -f $VERBOSE_ARG "$HOME/.codex/config.toml"
152	    $DRY_RUN_CMD install $VERBOSE_ARG -Dm644 ${codexConfig} "$HOME/.codex/config.toml"
153	  '';
154	}

